// ---------------------------------------------------------------------------
// schema
// ---------------------------------------------------------------------------

/// Local-only state with no Gmail representation: what you are still typing,
/// and what has not left yet.
///
/// `compose_outbox.rfc822` holds the finished message. Storing the bytes rather
/// than the draft fields is what makes the undo window safe: once the row is
/// committed, sending it needs no part of the UI to still exist, so closing the
/// window mid-window delays the send instead of losing it.
pub const COMPOSE_SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS compose_drafts (
    id            TEXT    PRIMARY KEY,
    account_id    INTEGER NOT NULL,
    -- The local thread row being replied to; NULL for a fresh message.
    thread_id     INTEGER,
    -- The local message row being replied to, so threading headers survive a
    -- restart along with the text.
    reply_to_id   INTEGER,
    kind          TEXT    NOT NULL DEFAULT 'new',
    to_json       TEXT    NOT NULL DEFAULT '[]',
    cc_json       TEXT    NOT NULL DEFAULT '[]',
    bcc_json      TEXT    NOT NULL DEFAULT '[]',
    subject       TEXT    NOT NULL DEFAULT '',
    -- The markdown-ish source, never the rendered HTML: the editor round-trips
    -- what the user typed, and HTML is produced once, at send.
    body          TEXT    NOT NULL DEFAULT '',
    updated_at    INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_compose_drafts_thread ON compose_drafts (thread_id);

CREATE TABLE IF NOT EXISTS compose_outbox (
    id              TEXT    PRIMARY KEY,
    account_id      INTEGER NOT NULL,
    thread_id       INTEGER,
    gmail_thread_id TEXT,
    subject         TEXT    NOT NULL DEFAULT '',
    -- The complete RFC822 message. Already built; the flusher only encodes it.
    rfc822          BLOB    NOT NULL,
    -- holding | sending | sent | failed
    state           TEXT    NOT NULL DEFAULT 'holding',
    -- Unix millis. Nothing leaves before this; the undo window is now + 10s and
    -- a scheduled send is whatever the user picked.
    send_after      INTEGER NOT NULL,
    created_at      INTEGER NOT NULL DEFAULT 0,
    attempts        INTEGER NOT NULL DEFAULT 0,
    last_error      TEXT,
    -- The Gmail message id once it has landed.
    sent_message_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_compose_outbox_due ON compose_outbox (state, send_after);
"#;

/// Idempotent. Called by every entry point into this module, so no caller has
/// to remember it.
pub fn ensure_compose_schema(conn: &Connection) -> DbResult<()> {
    conn.execute_batch(COMPOSE_SCHEMA)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// errors
// ---------------------------------------------------------------------------

#[derive(Debug, thiserror::Error)]
pub enum ComposeError {
    #[error("{0}")]
    Invalid(String),

    #[error("no thread with id {0} in the local store")]
    UnknownThread(i64),

    #[error("no account with id {0} in the local store")]
    UnknownAccount(i64),

    #[error("no message with id {0} in the local store")]
    UnknownMessage(i64),

    #[error("nothing in the outbox with id {0}")]
    UnknownOutbox(String),

    #[error("could not build the message: {0}")]
    Mime(String),

    #[error("local store: {0}")]
    Db(#[from] DbError),

    #[error("gmail: {0}")]
    Google(#[from] GoogleError),

    #[error(transparent)]
    Command(#[from] CommandError),
}

impl ComposeError {
    pub fn invalid(message: impl Into<String>) -> Self {
        ComposeError::Invalid(message.into())
    }

    /// The stable tag the frontend branches on.
    pub fn kind(&self) -> &'static str {
        match self {
            ComposeError::Invalid(_) => "invalid",
            ComposeError::UnknownThread(_) => "unknownThread",
            ComposeError::UnknownAccount(_) => "unknownAccount",
            ComposeError::UnknownMessage(_) => "unknownMessage",
            ComposeError::UnknownOutbox(_) => "unknownOutbox",
            ComposeError::Mime(_) => "mime",
            ComposeError::Db(_) => "db",
            ComposeError::Google(_) => "google",
            ComposeError::Command(inner) => inner.kind(),
        }
    }
}

pub type Result<T> = std::result::Result<T, ComposeError>;
